#include <bits/stdc++.h>
using namespace std;

void backtrack(vector<int>& nums, int index, vector<int>& current, vector<vector<int>>& result) {
    if (index == (int)nums.size()) {
        result.push_back(current);
        return;
    }
    backtrack(nums, index + 1, current, result);                      // exclude this element
    current.push_back(nums[index]);
    backtrack(nums, index + 1, current, result);                       // include this element
    current.pop_back();
}

vector<vector<int>> subsets(vector<int>& nums) {
    vector<vector<int>> result;
    vector<int> current;
    backtrack(nums, 0, current, result);
    return result;
}

int main() {
    vector<int> nums = {1, 2, 3};
    vector<vector<int>> result = subsets(nums);
    for (auto& s : result) {
        cout << "[";
        for (size_t i = 0; i < s.size(); i++) cout << s[i] << (i + 1 < s.size() ? "," : "");
        cout << "] ";
    }
    cout << endl;
    return 0;
}

