import java.util.*;

public class Main {
    List<List<Integer>> subsets(int[] nums) {
        int n = nums.length;
        List<List<Integer>> result = new ArrayList<>();
        for (int mask = 0; mask < (1 << n); mask++) {                // every number from 0 to 2^n minus 1
            List<Integer> current = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {                              // check whether bit i is set in this mask
                    current.add(nums[i]);
                }
            }
            result.add(current);
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.subsets(new int[]{1, 2, 3}));
    }
}

